"""A fixed-capacity LRU mapping; iteration runs from least to most recent."""

from __future__ import annotations

from collections import OrderedDict
from collections.abc import Iterator, MutableMapping
from typing import TypeVar

K = TypeVar("K")
V = TypeVar("V")


class LRUCache(MutableMapping[K, V]):
    """Reads and writes refresh recency; overflow evicts the oldest key.

    Capacity must be a nonnegative integer (excluding bool). A zero-capacity
    cache stores nothing. Missing reads raise KeyError without changing order.
    Keys must be hashable. Instances are not thread-safe; refreshing recency
    during iteration may invalidate the iterator, just like other mutations.
    """

    def __init__(self, capacity: int = 128) -> None:
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise TypeError("capacity must be an integer")
        if capacity < 0:
            raise ValueError("capacity must be nonnegative")
        self._capacity = capacity
        self._data: OrderedDict[K, V] = OrderedDict()

    @property
    def capacity(self) -> int:
        """The maximum number of entries (read-only)."""
        return self._capacity

    def __getitem__(self, key: K) -> V:
        value = self._data[key]
        self._data.move_to_end(key)
        return value

    def __setitem__(self, key: K, value: V) -> None:
        self._data[key] = value
        self._data.move_to_end(key)
        if len(self._data) > self._capacity:
            self._data.popitem(last=False)

    def __delitem__(self, key: K) -> None:
        del self._data[key]

    def __iter__(self) -> Iterator[K]:
        return iter(self._data)

    def __len__(self) -> int:
        return len(self._data)

    def __contains__(self, key: object) -> bool:
        """Check membership without refreshing recency."""
        return key in self._data

    def peek(self, key: K) -> V:
        """Return a value without refreshing recency; raise KeyError if absent."""
        return self._data[key]

    def clear(self) -> None:
        self._data.clear()
